1923	// sourceCredentials returns the credentials git authenticates the source
1924	// with on the endpoint's own site: the connection's (explicit, or
1925	// helper-resolved for that site — never ones looked up for a host a redirect
1926	// led to), else a token written into the endpoint URL. The latter never
1927	// becomes Auth — net/http derives Basic auth from req.URL.User on the git
1928	// requests — and the API request is built from a different URL, so it has to
1929	// be carried over here.
1930	func sourceCredentials(conn *gitproto.HTTPConn) gitproto.AuthMethod {
1931		if auth := conn.EndpointAuth(); auth != nil {
1932			return auth
1933		}
1934		if user := conn.EndpointURL.User; user != nil {
1935			if password, ok := user.Password(); ok && password != "" {
1936				return &transporthttp.BasicAuth{Username: user.Username(), Password: password}
1937			}
1938		}
1939		return nil
1940	}
