1942	func requestGitHubRepoSize(ctx context.Context, conn *gitproto.HTTPConn, auth gitproto.AuthMethod, lookup *githubSizeLookup) {
1943		apiURL := strings.TrimRight(GitHubRepoAPIBaseURL, "/") + "/repos/" + lookup.owner + "/" + lookup.repo
1944		req, err := http.NewRequestWithContext(ctx, http.MethodGet, apiURL, nil)
1945		if err != nil {
1946			lookup.err = fmt.Errorf("build request: %w", err)
1947			return
1948		}
1949		req.Header.Set("Accept", "application/vnd.github+json")
1950		req.Header.Set("X-Github-Api-Version", "2022-11-28")
1951		req.Header.Set("User-Agent", useragent.Plain())
1952		req.Header.Set(gitproto.StatsPhaseHeader, "github repo metadata")
1953		gitproto.ApplyAuth(req, auth)
1954		resp, err := conn.HTTP.Do(req)
1955		if err != nil {
1956			lookup.err = err
1957			return
1958		}
1959		defer resp.Body.Close()
1960		lookup.status = resp.StatusCode
1961		body := io.LimitReader(resp.Body, maxGitHubRepoResponseBytes)
1962		if resp.StatusCode != http.StatusOK {
1963			lookup.err = githubAPIError(resp.StatusCode, body)
1964			return
1965		}
1966		var payload struct {
1967			Size *int64 `json:"size"`
1968		}
1969		if err := json.NewDecoder(body).Decode(&payload); err != nil {
1970			lookup.err = fmt.Errorf("decode repository metadata: %w", err)
1971			return
1972		}
1973		// GitHub reports 0 both for an empty repository and for one whose size it
1974		// has not computed yet (a fresh push or import), so 0 is not a size.
1975		if payload.Size == nil || *payload.Size <= 0 {
1976			lookup.err = errors.New("repository metadata reports no size")
1977			return
1978		}
1979		lookup.sizeKB = *payload.Size
1980	}
